export class BidiBluetoothEmulation{#t;#e;constructor(t,e){this.#e=t,this.#t=e}async emulateAdapter(t,e=!0){await this.#t.send("bluetooth.simulateAdapter",{context:this.#e,state:t,leSupported:e})}async disableEmulation(){await this.#t.send("bluetooth.disableSimulation",{context:this.#e})}async simulatePreconnectedPeripheral(t){await this.#t.send("bluetooth.simulatePreconnectedPeripheral",{context:this.#e,address:t.address,name:t.name,manufacturerData:t.manufacturerData,knownServiceUuids:t.knownServiceUuids})}}